-- 0129: government (20-GOV) for the Ghāfir 40:2–3 roots, cleaned and made joinable.
--   + lemma_id      the AL lemma the row belongs to (nouns like تَنزِيل / عَزِيز / عَلِيم join too)
--   + harf_term_id  the ḥarf's meaning as a GT:harf_maani term (harf stays as ingested text)
--   + cite_json     a structured Qurʾān citation {surah, ayah, needle} beside the free-text qr_ref
-- QR's checked rows (qr_sarf_prep) come in as live rows; where AL already held the row live, the
-- AL row is completed instead. Mir drafts that a checked live row now covers are marked superseded
-- (kept, with their English), never deleted. مَعَ is a ẓarf, not a ḥarf jarr — noted on its row.
ALTER TABLE ar_ling_root_lemma_tadiya ADD COLUMN lemma_id TEXT;
ALTER TABLE ar_ling_root_lemma_tadiya ADD COLUMN harf_term_id TEXT;
ALTER TABLE ar_ling_root_lemma_tadiya ADD COLUMN cite_json TEXT;
